// The toString axes a RECORD-typed receiver has, in the shape a shipped
// package actually hands out. `protolong` is the [[Get]] sibling of this
// file; this one is only about the member the record type does NOT
// declare, which is the one JS still finds.
"use strict";

// Prototype toString -- protobufjs's `long` in miniature. Node answers
// L.prototype.toString; a receiver typed { low; toNumber() } does not
// declare toString at all, so the member resolves to
// Object.prototype.toString in the CHECKER while the VALUE has its own.
function L(lo) { this.low = 0 | lo }
L.prototype.toNumber = function () { return this.low >>> 0 };
L.prototype.toString = function () { return "L:" + this.low };
exports.makeProto = function (lo) { return new L(lo) };

// OWN toString, a data property on the instance.
function O(lo) {
  this.low = 0 | lo;
  this.toNumber = function () { return this.low >>> 0 };
  this.toString = function () { return "O:" + this.low };
}
exports.makeOwn = function (lo) { return new O(lo) };

// Shadowing: the OWN toString must win over the prototype's.
function S(lo) { this.low = 0 | lo; this.toString = function () { return "own:" + this.low } }
S.prototype.toNumber = function () { return this.low >>> 0 };
S.prototype.toString = function () { return "proto:" + this.low };
exports.makeShadow = function (lo) { return new S(lo) };

// No toString anywhere but Object.prototype -- the control. Node answers
// "[object Object]" here, and so must we.
function N(lo) { this.low = 0 | lo }
N.prototype.toNumber = function () { return this.low >>> 0 };
exports.makeNone = function (lo) { return new N(lo) };

// Two levels up.
function A() {}
function B(lo) { this.low = 0 | lo }
B.prototype = Object.create(A.prototype);
A.prototype.toNumber = function () { return this.low >>> 0 };
A.prototype.toString = function () { return "deep:" + this.low };
exports.makeDeep = function (lo) { return new B(lo) };
